print(f"Total parsed questions: {len(raw_questions)}")
assert len(raw_questions) == 300, f"Expected 300, got {len(raw_questions)}"

# Starting ID: 1794 (after 1793 questions)
start_id = 1794
ts_lines = [
  "import { RawMCQ } from './questionsData';",
  "",
  "// Exactly 300 Curated Verb & Non-Finite Verb Questions from MASTER English Grammar (Pages 1-29)",
  "export const BATCH_VERBS: RawMCQ[] = ["
]

for idx, item in enumerate(raw_questions):
    pdf_num, q_text, target, options, ans, meaning, exp, exam = item
    q_id = start_id + idx
    # Normalize answer to lowercase option key 'a', 'b', 'c', 'd'
    ans_key = ans.strip().lower()
    if ',' in ans_key:
        ans_key = ans_key.split(',')[0].strip()
    
    obj = {
        "id": q_id,
        "question": f"[{pdf_num}] {q_text}",
        "targetWord": target,
        "type": "verb",
        "category": "Verb",
        "examTag": exam,
        "options": options,
        "correctAnswer": ans_key,
        "wordMeaningBangla": meaning,
        "explanationBangla": exp
    }
    ts_lines.append("  " + json.dumps(obj, ensure_ascii=False) + ",")

ts_lines.append("];")
ts_lines.append("")

output_file = "src/data/questionsVerbs.ts"
with open(output_file, "w", encoding="utf-8") as f:
    f.write("\n".join(ts_lines))

print(f"Successfully written {len(raw_questions)} questions to {output_file} (IDs {start_id} to {start_id + len(raw_questions) - 1})")
